script.setup:
// FFmpeg rendered a Mandelbrot zoom on this computer (recipe ffmpeg.mandelbrot-zoom, a command_run);
// the scene plays the MP4 as a texture through a kaleidoscope.
ctx.state.video = await ctx.utils.createVideoTexture("mandelbrot.mp4", { loop: true, muted: true, wrap: "mirror" });
ctx.state.p = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, "#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_video; uniform vec2 u_resolution; uniform float u_time; uniform int u_segments; uniform float u_hue; uniform float u_zoom;
vec3 hueShift(vec3 c, float a){ const vec3 k = vec3(0.57735); float ca = cos(a); return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca); }
void main(){
  vec2 p = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);
  float r = length(p), a = atan(p.y, p.x) + u_time * 0.1;
  float seg = 6.2831853 / float(u_segments);
  a = abs(mod(a, seg) - seg * 0.5);
  vec2 q = vec2(cos(a), sin(a)) * r * u_zoom;
  vec3 c = texture(u_video, q * vec2(0.5625, 1.0) + 0.5).rgb;
  outColor = vec4(hueShift(c, u_hue * 6.2831853 + u_time * 0.05), 1.0);
}");

script.render:
const s = ctx.state;
s.video.update();
ctx.gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_video", s.video.texture, 0);
ctx.utils.drawFullscreen(s.p);
